    end
    -- Main:244
    local cg = Codegen.new(entry_class, entry_module.imports, externs, variant_owner, plat)
    -- Main:245
    local class_block = cg:class_block(entry_module.ast)
    -- Main:247
    local entry_sig = Option.unwrap_or(classes:get(entry_class), 0)
